p-recursion.code:
def cuenta(n):
    if n == 0:
        return 0
    return 1 + cuenta(n - 1)

print(cuenta(5))

p-worst-case.code:
def primer_par(nums):
    for x in nums:
        if x % 2 == 0:
            return x
    return None

print(primer_par([1, 3, 5, 6, 7]))

